import { ArrowLeft } from "lucide-react";
import { addGoalEditItem, editGoalEditItem, getGoalEditStepSequence, GoalEditSection, moveGoalEditStep, normalizeGoalEditDraftNavigation, removeGoalEditItem, selectGoalEditSections, updateGoalEditWorkingPlan } from "../domain/services/GoalEditDraftService";
import { acceptInterpretedPhase, acceptPhaseSuggestions, addManualPhase, assessPhaseRecommendationResult, beginPhaseIntent, chooseContinuousGoal, confirmInterpretedPhaseStartDate, discardPendingPhaseProposals, duplicateAuthoredPhase, estimatedPhaseTargetDate, interpretPhaseIntentDraft, isPhaseSectionResolved, moveAuthoredPhase, openAdvancedPhaseDetails, removeAuthoredPhase, requestPhaseRecommendation, resolvePhasePlanningEntry, restoreOriginalPhases, retainExistingPhaseStructure, revisePhaseIntentDraft, selectActiveAuthoredPhase, selectInterpretedPhaseProposal, setPhaseIntentText, setPhaseRevisionText, skipInterpretedPhaseProposal, updateAuthoredPhase, validatePhaseEditingDraft } from "../domain/services/GoalEditPhaseDraftService";
