const CHOICES=[["goal_and_purpose","Goal and purpose"],["phases","Phases"],["overall_goal","Overall goal"],["success_criteria","Success criteria"],["guardrails","Guardrails"],["coaching_preferences","Coaching preferences"]];
const input="input-shell mt-2 w-full";
export default function GoalEditWizardScreen({goalHref,initialDraft,prepareReview,preparePhaseReview,saveChanges,savePhaseChanges}){
 const [draft,setDraft]=useState(()=>normalizeGoalEditDraftNavigation(initialDraft)),[selected,setSelected]=useState([]),[error,setError]=useState(""),[review,setReview]=useState(null),[commit,setCommit]=useState(null),[pending,startTransition]=useTransition(); const step=draft.currentStep;
 const run=fn=>{try{setDraft(fn());setError("");setReview(null);setCommit(null)}catch(e){setError(e.message)}};
 function choose(){run(()=>{const selectedDraft=selectGoalEditSections(draft,selected);return selectedDraft.currentStep==="phases"?resolvePhasePlanningEntry(selectedDraft):selectedDraft})} function patch(value){run(()=>updateGoalEditWorkingPlan(draft,value))}
 function next(){if(step!=="review")return run(()=>{if(step==="phases"&&!isPhaseSectionResolved(draft))return draft;const moved=moveGoalEditStep(draft,"forward");return moved.currentStep==="phases"?resolvePhasePlanningEntry(moved):moved}); const goalDiff=diffGoalPlans(draft.originalPlan,draft.workingPlan),phaseDiff=draft.phaseEditing?.diff; if(!goalDiff.empty&&phaseDiff&&!phaseDiff.empty){setReview({status:"combined_changes_blocked",message:"Goal-plan and phase changes cannot be saved together. Save one category, then reopen this wizard for the other."});return} startTransition(async()=>setReview(phaseDiff&&!phaseDiff.empty?await preparePhaseReview(draft):await prepareReview(draft)))}
 function save(){startTransition(async()=>{const kind=goalEditSaveKind(review);setCommit(kind==="phase"?await savePhaseChanges(draft,review):kind==="goal"?await saveChanges(draft,review):{status:"rejected",reasonCode:"REVIEW_TOKEN_INVALID",message:"Prepare Final Review again before saving.",draftPreserved:true,recommendedAction:"Prepare Final Review again."})})}
 function back(){run(()=>moveGoalEditStep(draft,"back"))}
 const phaseAvailable=draft.phaseEditing?.capability?.available===true;
 return <main className="app-surface min-h-screen overflow-x-hidden" data-current-section={step} data-selected-sections={draft.selectedSections.join(",")}><div className="mx-auto w-full max-w-[393px] px-4 pb-[calc(8rem+env(safe-area-inset-bottom))] pt-8"><Link className="inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-[var(--text-secondary)]" href="/goals"><ArrowLeft size={18}/>Goals</Link><p className="mt-5 text-[10px] font-black uppercase tracking-[.14em] text-[var(--primary)]">Goal Edit</p><h1 className="mt-2 text-3xl font-black text-[var(--text-primary)]">{title(step)}</h1><p className="mt-2 text-sm font-semibold leading-6 text-[var(--text-secondary)]">Your active goal will not change while you edit or review this draft.</p>
 <div className="mt-6 rounded-[24px] border border-[var(--divider)] bg-[var(--surface-elevated)] p-4 sm:p-5">
 {step==="choose_sections"&&<div className="space-y-3">{CHOICES.map(([id,label])=>id!=="phases"||phaseAvailable?<Choice key={id} id={id} label={label} selected={selected} setSelected={setSelected}/>:<div className="rounded-xl bg-[var(--surface-muted)] p-3" key={id}><b>Phases unavailable</b><p className="mt-1 text-xs text-[var(--text-secondary)]">{(draft.phaseEditing?.capability?.blockingReasons??["Phase persistence is unavailable."]).join(", ")}</p></div>)}<button className="min-h-12 w-full rounded-xl bg-[var(--primary)] font-extrabold text-white disabled:opacity-50" disabled={!selected.length} onClick={choose}>Continue</button></div>}
 {step!=="choose_sections"&&<SectionEditor commit={commit} draft={draft} goalHref={goalHref} onPatch={patch} onSave={save} pending={pending} review={review} setDraft={setDraft} setError={setError} step={step}/>} {error&&<p aria-live="assertive" className="mt-4 rounded-xl bg-red-50 p-3 text-sm font-bold text-red-700 dark:bg-red-950 dark:text-red-200">{error}</p>}</div>
 {step!=="choose_sections"&&<div className="mt-5 flex gap-3"><button className="min-h-12 flex-1 rounded-xl border border-[var(--divider)] font-extrabold" onClick={back}>Back</button>{!(step==="phases"&&!isPhaseSectionResolved(draft))&&<button className="min-h-12 flex-1 rounded-xl bg-[var(--primary)] px-2 font-extrabold text-white disabled:opacity-50" disabled={pending||Boolean(review)||(step==="phases"&&!validatePhaseEditingDraft(draft).valid)} onClick={next}>{step==="review"?"Prepare final review":"Continue"}</button>}</div>}<p className="mt-4 text-center text-xs font-semibold text-[var(--text-muted)]">Step {Math.max(1,getGoalEditStepSequence(draft).indexOf(step)+1)} of {getGoalEditStepSequence(draft).length}</p></div></main>;
}
function Choice({id,label,selected,setSelected}){const inputId=`goal-edit-section-${id}`;return <div className="flex min-h-12 items-center gap-3 rounded-xl border border-[var(--divider)] p-3"><input checked={selected.includes(id)} id={inputId} value={id} onChange={()=>setSelected(selected.includes(id)?selected.filter(x=>x!==id):[...selected,id])} type="checkbox"/><label className="flex-1" htmlFor={inputId}>{label}</label></div>}
function SectionEditor({step,draft,setDraft,setError,onPatch,review,pending,onSave,commit,goalHref}){switch(step){case GoalEditSection.GOAL_AND_PURPOSE:return <section data-editor-type="goal_and_purpose_editor"><Fields fields={[["name","Goal name"],["purpose","Purpose"],["primaryOutcome","Primary outcome"]]} onChange={(key,value)=>onPatch({[key]:value})} values={draft.workingPlan}/></section>;case GoalEditSection.PHASES:return <section data-editor-type="phase_editor"><PhaseEditor draft={draft} setDraft={setDraft} setError={setError}/></section>;case GoalEditSection.OVERALL_GOAL:return <section data-editor-type="overall_goal_destination_editor"><TargetTimeline onPatch={onPatch} plan={draft.workingPlan}/></section>;case GoalEditSection.SUCCESS_CRITERIA:return <section data-editor-type="success_criteria_editor"><Items collection="successCriteria" draft={draft} label="criterion" setDraft={setDraft}/></section>;case GoalEditSection.GUARDRAILS:return <section data-editor-type="guardrails_editor"><Items collection="guardrails" draft={draft} label="guardrail" setDraft={setDraft}/></section>;case GoalEditSection.COACHING:return <section data-editor-type="coaching_preferences_editor"><p className="text-sm font-bold">Briefing cadence, reminders, and scheduling remain unchanged.</p></section>;case GoalEditSection.REVIEW:return <section data-editor-type="review"><ReviewOwnership draft={draft}/><Review commit={commit} draft={draft} goalHref={goalHref} onSave={onSave} pending={pending} review={review}/></section>;default:return <section data-editor-type="unavailable"><h2 className="font-black">This editing section is unavailable</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">Return to section selection and choose what you want to edit.</p></section>}}
function PhaseEditor({draft,setDraft,setError}){const p=draft.phaseEditing,phases=p.workingAuthoredPhases,apply=fn=>{try{setDraft(fn());setError("")}catch(e){setError(e.message)}};if(!p.structureChoice&&!phases.length)return <div><h2 className="text-xl font-black">How do you see this journey unfolding?</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">Start with a suggested path, describe your own, or keep the goal continuous.</p><div className="mt-5 space-y-3"><PhaseButton onClick={()=>apply(()=>requestPhaseRecommendation(draft))}>Show me a suggested path</PhaseButton><PhaseButton onClick={()=>apply(()=>beginPhaseIntent(draft))}>Describe the phases in my own words</PhaseButton><PhaseButton onClick={()=>apply(()=>chooseContinuousGoal(draft))}>Keep this as one continuous goal</PhaseButton></div></div>;
if(p.recommendationDecision==="reviewing"){const availability=assessPhaseRecommendationResult(p.recommendationResult);return availability.available?<CanonicalSuggestionReview availability={availability} draft={draft} apply={apply}/>:<PlanIntentEntry draft={draft} apply={apply} incomplete/>}
if(p.intentPlanning?.mode==="describe")return <PlanIntentEntry draft={draft} apply={apply}/>;
if(p.intentPlanning?.mode==="plan_review")return <InterpretedPlanReview draft={draft} apply={apply}/>;
if(p.intentPlanning?.mode&&!["idle","accepted","advanced"].includes(p.intentPlanning.mode))return <IntentPhasePlanner draft={draft} apply={apply}/>;
if(p.intentPlanning?.mode==="accepted")return <><AcceptedPhasePlan draft={draft} apply={apply}/>{p.recommendationDecision==="existing_review"&&<><PhaseButton onClick={()=>apply(()=>retainExistingPhaseStructure(draft))}>Keep current phase plan</PhaseButton><PhaseButton onClick={()=>confirm("Remove the explicit phase structure and keep this goal continuous?")&&apply(()=>chooseContinuousGoal(draft))}>Keep this goal continuous</PhaseButton></>}</>;
return <div><div className="rounded-xl bg-[var(--surface-muted)] p-3 text-sm"><b>Keep the journey clear.</b><p className="mt-1 text-[var(--text-secondary)]">Your overall goal remains the destination. Each phase describes the work that moves you toward it.</p></div>{!phases.length?<div className="mt-5"><p className="text-sm font-bold">This goal will remain one continuous journey.</p><PhaseButton onClick={()=>apply(()=>addManualPhase(draft))}>Add phase</PhaseButton></div>:<><div className="mt-5 space-y-4">{phases.map((phase,index)=><PhaseCard key={phase.id} phase={phase} index={index} count={phases.length} draft={draft} apply={apply}/>)}</div><PhaseButton onClick={()=>apply(()=>addManualPhase(draft))}>Add phase</PhaseButton><section className="mt-6 rounded-xl border-2 border-[var(--primary)] p-4"><h3 className="font-black">Which phase are you in now?</h3><p className="mt-1 text-xs text-[var(--text-secondary)]">Choose the phase that best matches your current work.</p>{phases.map(x=><label className="mt-3 flex items-center gap-3 text-sm font-bold" key={x.id}><input checked={p.selectedActivePhaseId===x.id} name="active-phase" onChange={()=>apply(()=>selectActiveAuthoredPhase(draft,x.id))} type="radio"/>{x.name} — {p.selectedActivePhaseId===x.id?"Current":"Next"}</label>)}</section></>}<button className="mt-5 min-h-11 text-sm font-extrabold text-[var(--primary)]" onClick={()=>apply(()=>restoreOriginalPhases(draft))}>Restore original phase plan</button>{!p.validation.valid&&<p className="mt-3 text-sm font-bold text-red-600">{p.validation.errors[0]?.message}</p>}<p className="mt-4 text-xs text-[var(--text-secondary)]">Your protocols, briefings, and schedule will stay as they are.</p></div>}
function PhaseCard({phase,index,count,draft,apply}){const update=patch=>apply(()=>updateAuthoredPhase(draft,phase.id,patch)),criteria=phase.successCriteria.map(label).join("\n"),expected=estimatedPhaseTargetDate(phase);const changeMode=timingMode=>update({timingMode,duration:timingMode==="fixed_duration"?(phase.duration??{value:4,unit:"weeks"}):null,targetDate:timingMode==="target_date"?phase.targetDate:null});return <article className="min-w-0 rounded-2xl border border-[var(--divider)] p-4"><div className="flex items-center justify-between gap-2"><div><p className="text-xs font-bold text-[var(--text-muted)]">Edit phase</p><h3 className="font-black">Phase {index+1}</h3></div><span className="text-xs font-bold text-[var(--text-muted)]">{human(phase.status)}</span></div><Fields fields={[["name","Phase name"],["purpose","Why this phase exists"]]} values={phase} onChange={(k,v)=>update({[k]:v})}/><div className="mt-4 space-y-4"><label className="block text-sm font-extrabold">How should this phase be planned?<select className={input} value={phase.timingMode} onChange={e=>changeMode(e.target.value)}><option value="fixed_duration">Planned duration</option><option value="target_date">Reach a target date</option><option value="completion_criteria">Open-ended and evidence-led</option></select></label>{phase.timingMode==="fixed_duration"&&<><label className="block text-sm font-extrabold">When should this phase begin?<input className={input} type="date" value={phase.startDate??""} onChange={e=>update({startDate:e.target.value||null})}/></label><div className="grid grid-cols-2 gap-2"><label className="text-sm font-extrabold">Planned duration<input className={input} min="1" type="number" value={phase.duration?.value??""} onChange={e=>update({duration:{value:Number(e.target.value),unit:phase.duration?.unit??"weeks"}})}/></label><label className="text-sm font-extrabold">Unit<select className={input} value={phase.duration?.unit??"weeks"} onChange={e=>update({duration:{value:phase.duration?.value??4,unit:e.target.value}})}><option value="days">days</option><option value="weeks">weeks</option><option value="months">months</option></select></label></div>{expected&&<p className="text-sm"><b>Expected phase review:</b> {formatDate(expected)}</p>}</>}{phase.timingMode==="target_date"&&<label className="block text-sm font-extrabold">When should this phase reach its target?<input className={input} type="date" value={phase.targetDate??""} onChange={e=>update({targetDate:e.target.value||null})}/></label>}{phase.timingMode==="completion_criteria"&&<p className="text-sm text-[var(--text-secondary)]">No planned end date. We’ll review the evidence together when the phase looks complete.</p>}<p className="text-xs leading-5 text-[var(--text-secondary)]">This is the initial plan. PhysiqueOS may recommend extending or shortening the phase as evidence comes in.</p></div><TextList labelText="What success looks like" value={criteria} onChange={v=>update({successCriteria:lines(v)})}/><GoalConditions draft={draft}/><PhaseProtectionEditor apply={apply} draft={draft} phase={phase}/><label className="mt-4 block text-sm font-extrabold">What happens next?<select className={input} value={phase.transitionPolicy} onChange={e=>update({transitionPolicy:e.target.value})}><option value="manual_review">We review together before moving on</option><option value="evidence_review">We review the evidence together before moving on</option><option value="automatic">Move on when this phase looks complete</option></select></label><div className="mt-5 grid grid-cols-2 gap-3 text-xs font-extrabold"><button aria-label={`Move ${phase.name} up`} disabled={!index} onClick={()=>apply(()=>moveAuthoredPhase(draft,phase.id,"earlier"))}>Move up</button><button aria-label={`Move ${phase.name} down`} disabled={index===count-1} onClick={()=>apply(()=>moveAuthoredPhase(draft,phase.id,"later"))}>Move down</button><button onClick={()=>apply(()=>duplicateAuthoredPhase(draft,phase.id))}>Duplicate</button><button className="text-red-600" onClick={()=>confirm(`Remove ${phase.name}?`)&&apply(()=>removeAuthoredPhase(draft,phase.id))}>Remove</button></div></article>}

function GoalConditions({draft,compact=false}){const plan=draft.workingPlan,conditions=(plan.guardrails??[]).map(label).filter(Boolean),destination=overallDestination(plan);if(!destination&&!conditions.length)return null;return <section className={compact?"mt-3":"mt-5 rounded-xl bg-[var(--surface-muted)] p-3"}><h4 className="font-black">Overall goal</h4>{destination&&<p className="mt-1 text-sm font-bold">{destination}</p>}{plan.timeline?.startDate&&<p className="mt-2 text-xs"><b>Journey begins:</b> {formatDate(plan.timeline.startDate)}</p>}{conditions.length>0&&<><h5 className="mt-3 text-xs font-black">Still protecting</h5>{conditions.map(condition=><p className="mt-1 text-sm" key={condition}>{condition}</p>)}<p className="mt-1 text-xs text-[var(--text-secondary)]">This stays in effect throughout every phase.</p></>}</section>}
function PhaseProtectionEditor({phase,draft,apply}){const [open,setOpen]=useState(phase.guardrails.length>0),value=phase.guardrails.map(label).join("\n");return <section className="mt-5"><h4 className="font-black">Phase-specific protections</h4>{phase.guardrails.length>0&&phase.guardrails.map(item=><p className="mt-1 text-sm" key={label(item)}>{label(item)}</p>)}{!open&&<button className="mt-2 min-h-11 text-sm font-extrabold text-[var(--primary)]" onClick={()=>setOpen(true)}>Add a phase-specific protection</button>}{open&&<div><p className="mt-1 text-xs text-[var(--text-secondary)]">Add something that should apply only during this phase.</p><TextList labelText="Phase-specific protections" value={value} onChange={text=>apply(()=>updateAuthoredPhase(draft,phase.id,{guardrails:lines(text)}))}/><button className="mt-2 text-xs font-bold text-[var(--text-secondary)]" onClick={()=>{apply(()=>updateAuthoredPhase(draft,phase.id,{guardrails:[]}));setOpen(false)}}>Remove phase-specific protections</button></div>}</section>}
function IntentPhasePlanner({draft,apply}){const planning=draft.phaseEditing.intentPlanning,result={...planning.result,ownershipNotes:(draft.workingPlan.guardrails??[]).map(label).filter(Boolean).map(condition=>`${condition} — This stays in effect during every phase.`)};if(planning.mode==="describe")return <PlanIntentEntry draft={draft} apply={apply}/>;
if(planning.mode==="clarification_required")return <div><h2 className="text-xl font-black">I need a little more detail</h2>{result.clarificationQuestions.map(question=><p className="mt-3 rounded-xl bg-[var(--surface-muted)] p-3 text-sm" key={question}>{question}</p>)}<textarea aria-label="Clarification" className={`${input} min-h-28`} value={planning.intentText} onChange={e=>apply(()=>setPhaseIntentText(draft,e.target.value))}/><PhaseButton onClick={()=>apply(()=>interpretPhaseIntentDraft(draft))}>Show me the updated plan</PhaseButton><PhaseButton onClick={()=>apply(()=>beginPhaseIntent(draft))}>Start over</PhaseButton></div>;
if(planning.mode==="rejected")return <div><h2 className="text-xl font-black">I need a phase description</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">{result.warnings[0]??result.clarificationQuestions[0]}</p><PhaseButton onClick={()=>apply(()=>beginPhaseIntent(draft))}>Back</PhaseButton></div>;
if(planning.mode==="revise")return <div><h2 className="text-xl font-black">What should I change?</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">Tell me what you’d like to change. Everything else will stay as you approved it.</p><textarea aria-label="Phase revision" className={`${input} min-h-32`} placeholder="Make it six weeks instead." value={planning.revisionText} onChange={e=>apply(()=>setPhaseRevisionText(draft,e.target.value))}/><button className="mt-4 min-h-12 w-full rounded-xl bg-[var(--primary)] font-extrabold text-white disabled:opacity-50" disabled={!planning.revisionText.trim()} onClick={()=>apply(()=>revisePhaseIntentDraft(draft))}>Show me the update</button><PhaseButton onClick={()=>apply(()=>interpretPhaseIntentDraft(draft))}>Back</PhaseButton></div>;
if(planning.mode==="review"&&result?.proposedPhase){const phase=result.proposedPhase,estimated=estimatedPhaseTargetDate(phase),number=(result.currentProposalIndex??0)+1,total=result.proposedPhases?.length??1;return <div><p className="text-xs font-bold text-[var(--text-muted)]">Phase {number} of {total}</p><h2 className="mt-1 text-xl font-black">Here’s what I understood</h2><section className="mt-4 space-y-3 rounded-2xl border border-[var(--divider)] p-4"><div><p className="text-xs font-bold text-[var(--text-muted)]">Phase</p><p className="font-black">{phase.name}</p></div><div><p className="text-xs font-bold text-[var(--text-muted)]">Purpose</p><p className="text-sm">{phase.purpose}</p></div>{phase.timingMode==="fixed_duration"&&<><p className="text-sm"><b>Planned duration:</b> {phase.duration?.value} {phase.duration?.unit}</p>{phase.startDate?<p className="text-sm"><b>Start:</b> {formatDate(phase.startDate)}</p>:<div><label className="block text-sm font-extrabold">When should this phase begin?<input className={input} type="date" onChange={e=>e.target.value&&apply(()=>confirmInterpretedPhaseStartDate(draft,e.target.value))}/></label><PhaseButton onClick={()=>apply(()=>confirmInterpretedPhaseStartDate(draft,"today"))}>Today</PhaseButton></div>}{estimated&&<p className="text-sm"><b>Expected phase review:</b> {formatDate(estimated)}</p>}</>}{phase.timingMode==="target_date"&&<p className="text-sm"><b>Target date:</b> {formatDate(phase.targetDate)}</p>}{phase.timingMode==="completion_criteria"&&<p className="text-sm">No planned end date. This phase ends after an evidence review.</p>}<p className="text-xs text-[var(--text-secondary)]">This is the initial plan. PhysiqueOS may recommend extending or shortening the phase as evidence comes in.</p></section><section className="mt-4"><h3 className="font-black">I’ll coach this phase by watching</h3>{result.evidenceMonitoringPlan.length?result.evidenceMonitoringPlan.map(item=><div className="mt-2 rounded-xl bg-[var(--surface-muted)] p-3" key={item.area}><p className="text-sm font-bold">{item.label}</p><p className="mt-1 text-xs text-[var(--text-secondary)]">{item.purpose}</p></div>):<p className="mt-2 text-sm text-[var(--text-secondary)]">We’ll use your check-ins to understand how the phase is progressing.</p>}</section><section className="mt-4"><h3 className="font-black">What success looks like</h3>{result.completionCriteria.length?result.completionCriteria.map(item=><p className="mt-2 text-sm" key={item.key}>{item.label}</p>):<p className="mt-2 text-sm text-[var(--text-secondary)]">We’ll look at your progress together and decide when you’re ready for what comes next.</p>}</section>{result.ownershipNotes.length>0&&<section className="mt-4 rounded-xl border border-[var(--divider)] p-3"><h3 className="font-black">Overall goal</h3>{result.ownershipNotes.map(note=><p className="mt-2 text-xs text-[var(--text-secondary)]" key={note}>{note}</p>)}</section>}<p className="mt-4 text-sm"><b>What happens next:</b> {transitionLabel(phase.transitionPolicy)}</p><div className="mt-5 space-y-2"><button className="min-h-12 w-full rounded-xl bg-[var(--primary)] font-extrabold text-white" onClick={()=>apply(()=>acceptInterpretedPhase(draft))}>Accept this phase</button><PhaseButton onClick={()=>apply(()=>setPhaseRevisionText(draft,""))}>Tell PhysiqueOS what to change</PhaseButton><PhaseButton onClick={()=>apply(()=>skipInterpretedPhaseProposal(draft))}>Skip this phase</PhaseButton><PhaseButton onClick={()=>confirm("Discard the remaining unaccepted phases and start over?")&&apply(()=>beginPhaseIntent(discardPendingPhaseProposals(draft)))}>Start over</PhaseButton></div></div>}return null}
function transitionLabel(value){return ({manual_review:"When this phase looks complete, we’ll review it together before moving on.",evidence_review:"When this phase looks complete, we’ll review the evidence together before moving on.",automatic:"When this phase looks complete, we’ll confirm you’re ready for what comes next."})[value]??"We’ll review this phase together before moving on."}
function AcceptedPhasePlan({draft,apply}){const phases=draft.phaseEditing.workingAuthoredPhases,selected=draft.phaseEditing.selectedActivePhaseId;return <div><h2 className="text-xl font-black">Your phase plan</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">Here’s how the journey is currently laid out.</p><GoalConditions draft={draft}/>{phases.map((phase,index)=><article className="mt-4 rounded-2xl border border-[var(--divider)] p-4" key={phase.id}><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold text-[var(--text-muted)]">Phase {index+1}</p><p className="text-xs font-bold text-[var(--text-muted)]">{human(phase.status)}</p></div><h3 className="mt-1 font-black">{phase.name}</h3><p className="mt-2 text-sm">{phase.purpose}</p><p className="mt-2 text-xs text-[var(--text-secondary)]">{phaseDateSummary(phase)}</p><h4 className="mt-3 text-sm font-black">What success looks like</h4>{phase.successCriteria.length?phase.successCriteria.map(item=><p className="mt-1 text-sm" key={label(item)}>{label(item)}</p>):<p className="mt-1 text-sm text-[var(--text-secondary)]">No additional success criteria.</p>}<h4 className="mt-3 text-sm font-black">Phase-specific protections</h4>{phase.guardrails.length?phase.guardrails.map(item=><p className="mt-1 text-sm" key={label(item)}>{label(item)}</p>):<p className="mt-1 text-sm text-[var(--text-secondary)]">No additional phase-specific protections.</p>}</article>)}<PhaseButton onClick={()=>apply(()=>beginPhaseIntent(draft))}>Describe another phase</PhaseButton><PhaseButton onClick={()=>apply(()=>openAdvancedPhaseDetails(draft))}>Edit phase details</PhaseButton><section className="mt-6 rounded-xl border-2 border-[var(--primary)] p-4"><h3 className="font-black">Which phase are you in now?</h3><p className="mt-1 text-xs text-[var(--text-secondary)]">Choose the phase that best matches your current work.</p>{phases.map(phase=><label className="mt-3 flex items-center gap-3 text-sm font-bold" key={phase.id}><input checked={selected===phase.id} name="accepted-active-phase" type="radio" onChange={()=>apply(()=>selectActiveAuthoredPhase(draft,phase.id))}/>{phase.name}</label>)}</section></div>}
function PlanIntentEntry({draft,apply,incomplete=false}){const planning=draft.phaseEditing.intentPlanning;return <div data-entry-diagnostic={draft.phaseEditing.entryDiagnostic??undefined}><h2 className="text-xl font-black">{incomplete?"I need a little more detail":"Tell us how you envision the phases"}</h2><p className="mt-2 text-sm leading-6 text-[var(--text-secondary)]">Describe how you expect this goal to unfold. Include any stages, timing, milestones, or conditions you already have in mind, and PhysiqueOS will turn that into a structured plan.</p><textarea aria-label="Phase plan intent" className={`${input} min-h-44 resize-y`} placeholder="Start with an initial calibration period, then describe the next stage, its timing, milestones, and anything that should remain protected." value={planning.intentText} onChange={e=>apply(()=>setPhaseIntentText(draft,e.target.value))}/><p className="mt-2 text-xs text-[var(--text-secondary)]">Type your plan in your own words.</p><button className="mt-4 min-h-12 w-full rounded-xl bg-[var(--primary)] font-extrabold text-white disabled:opacity-50" disabled={!planning.intentText.trim()} onClick={()=>apply(()=>interpretPhaseIntentDraft(draft))}>Interpret my plan</button><PhaseButton onClick={()=>apply(()=>chooseContinuousGoal(draft))}>Keep this goal continuous</PhaseButton></div>}
function InterpretedPlanReview({draft,apply}){const result=draft.phaseEditing.intentPlanning.result;return <div><h2 className="text-xl font-black">Here’s the phase structure I understood</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">Review each phase before it becomes part of your plan.</p><div className="mt-4 space-y-3">{result.proposedPhases.map((item,index)=><article className="rounded-xl border border-[var(--divider)] p-3" key={item.proposalKey}><p className="text-xs font-bold text-[var(--text-muted)]">{index+1}. {item.state==="pending_review"?"Ready to review":human(item.state)}</p><h3 className="mt-1 font-black">{item.phase.name}</h3><p className="mt-1 text-sm">{item.phase.purpose}</p><PhaseButton onClick={()=>apply(()=>selectInterpretedPhaseProposal(draft,index))}>Review Phase {index+1}</PhaseButton></article>)}</div><PhaseButton onClick={()=>apply(()=>setPhaseRevisionText(draft,""))}>Revise the whole plan</PhaseButton><PhaseButton onClick={()=>confirm("Discard this interpreted plan and start over?")&&apply(()=>beginPhaseIntent(discardPendingPhaseProposals(draft)))}>Start over</PhaseButton><PhaseButton onClick={()=>apply(()=>chooseContinuousGoal(draft))}>Keep the goal continuous</PhaseButton></div>}
function CanonicalSuggestionReview({draft,apply,availability}){return <div><h2 className="text-xl font-black">Here’s a suggested phase structure</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">This path reflects the destination and milestones you’ve described.</p><div className="mt-4 space-y-3">{availability.suggestions.map((phase,index)=><article className="rounded-xl border border-[var(--divider)] p-3" key={`${phase.name}-${index}`}><h3 className="font-black">{index+1}. {phase.name}</h3><p className="mt-1 text-sm">{phase.purpose}</p><p className="mt-2 text-xs text-[var(--text-secondary)]">{phaseDateSummary(phase)}</p></article>)}</div><p className="mt-3 text-xs text-[var(--text-secondary)]">Your destination and the things you want to protect still apply throughout every phase.</p><div className="mt-5 space-y-2"><PhaseButton onClick={()=>apply(()=>acceptPhaseSuggestions(draft))}>Use this structure</PhaseButton><PhaseButton onClick={()=>apply(()=>acceptPhaseSuggestions(draft,{customize:true}))}>Customize phases</PhaseButton><PhaseButton onClick={()=>apply(()=>beginPhaseIntent(draft))}>Describe different phases</PhaseButton><PhaseButton onClick={()=>apply(()=>chooseContinuousGoal(draft))}>Keep this goal continuous</PhaseButton></div></div>}
function TextList({labelText,value,onChange}){return <label className="mt-4 block text-sm font-extrabold">{labelText}<textarea className={`${input} min-h-20`} value={value} onChange={e=>onChange(e.target.value)}/><span className="mt-1 block text-[10px] font-medium text-[var(--text-muted)]">One item per line</span></label>}
function ReviewOwnership({draft}){const goalDiff=diffGoalPlans(draft.originalPlan,draft.workingPlan);if(goalDiff.empty)return null;const phases=draft.phaseEditing?.workingAuthoredPhases??[];return <section className="mb-4 text-sm"><div className="rounded-xl bg-[var(--surface-muted)] p-3"><h2 className="font-black">Overall goal changes</h2><p className="mt-1 text-[var(--text-secondary)]">This destination will be updated through the Goal Plan save.</p></div><GoalConditions draft={draft}/>{phases.length>0&&<section className="mt-4"><h3 className="font-black">Planned journey — retained</h3>{phases.map((phase,index)=><p className="mt-1" key={phase.id}>{index+1}. {phase.name}</p>)}</section>}</section>}
function Review({draft,review,pending,onSave,commit,goalHref}){const pd=draft.phaseEditing?.diff;if(pending)return <p>Preparing your review…</p>;if(commit){if(commit.status==="committed")return <div><h2 className="text-xl font-black">{commit.committedPhases?"Goal phases updated":"Goal updated"}</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">Your changes are saved. Your evidence and history are right where you left them.</p><Link className="mt-5 inline-flex min-h-12 w-full items-center justify-center rounded-xl bg-[var(--primary)] font-extrabold text-white" href={goalHref}>Back to goal</Link></div>;return <Failure value={commit}/>}if(review){if(review.status==="combined_changes_blocked")return <Failure value={review}/>;if(review.status==="no_changes")return <div><h2 className="text-xl font-black">No changes to save</h2></div>;if(review.status!=="ready")return <Failure value={review}/>;return <div><h2 className="text-xl font-black">Ready to save</h2>{review.token?.version==="goal_phase_review_v1"?<PhaseSummary draft={draft}/>:<p className="mt-3 text-sm">Your updated overall goal is ready.</p>}<button className="mt-5 min-h-12 w-full rounded-xl bg-[var(--primary)] font-extrabold text-white" disabled={!review.commitAvailable} onClick={onSave}>{review.token?.version==="goal_phase_review_v1"?"Save Phase Changes":"Save Goal Changes"}</button></div>}return <div><h2 className="text-xl font-black">Review changes</h2>{pd&&!pd.empty?<PhaseSummary draft={draft}/>:<p className="mt-2 text-sm text-[var(--text-secondary)]">Take one last look before saving your changes.</p>}</div>}
function PhaseSummary({draft}){const planned=draft.phaseEditing.workingAuthoredPhases,hasPhaseProtections=planned.some(phase=>phase.guardrails.length);return <div className="mt-3 space-y-3 text-sm"><GoalConditions draft={draft}/><section><h3 className="font-black">Planned journey</h3>{planned.map((phase,index)=><article className="mt-3 rounded-xl border border-[var(--divider)] p-3" key={phase.id}><p className="font-black">Phase {index+1} — {phase.name}</p><p className="text-xs font-bold capitalize text-[var(--text-muted)]">{human(phase.status)}</p>{index>0&&<p className="mt-1 text-xs text-[var(--text-secondary)]">Builds toward the overall destination from the established baseline.</p>}{phase.timingMode==="fixed_duration"&&<><p>Begins: {formatDate(phase.startDate)}</p><p>Planned duration: {phase.duration.value} {phase.duration.unit}</p><p>Planned review: {formatDate(estimatedPhaseTargetDate(phase))}</p></>}{phase.timingMode==="target_date"&&<><p>Target date: {formatDate(phase.targetDate)}</p>{!phase.startDate&&index>0&&<p>Begins after Phase {index} review.</p>}</>}{phase.timingMode==="completion_criteria"&&<p>No planned end date; this phase ends after evidence review.</p>}<p className="text-xs text-[var(--text-secondary)]">Timing may be adjusted based on progress.</p>{hasPhaseProtections&&<section className="mt-2"><h4 className="font-black">Phase-specific</h4>{phase.guardrails.length?phase.guardrails.map(item=><p key={label(item)}>{label(item)}</p>):<p className="text-[var(--text-secondary)]">None</p>}</section>}</article>)}</section>{!hasPhaseProtections&&<p><b>Phase-specific protections:</b> No additional protections.</p>}<p>Existing evidence and history remain intact.</p></div>}
function Failure({value}){const reason=value?.reasonCode??"UNKNOWN",copy=resultCopy(value),guidance=[...(value?.sectionErrors??[]),...Object.entries(value?.fieldErrors??{}).map(([field,message])=>({field,message})),...(value?.errors??[])];return <div data-result-reason={reason} data-result-status={value?.status??"unknown"}><h2 className="text-xl font-black">{copy.title}</h2><p className="mt-2 text-sm text-[var(--text-secondary)]">{copy.body}</p>{guidance.length>0&&<ul className="mt-3 space-y-1 text-sm">{guidance.map((item,index)=><li key={`${item.field??item.code??"guidance"}-${index}`}>{item.message??String(item)}</li>)}</ul>}{value?.recommendedAction&&<p className="mt-3 text-sm font-bold">{value.recommendedAction}</p>}<p className="mt-3 text-xs text-[var(--text-muted)]">Your draft is still here. No automatic retry was attempted.</p></div>}
function resultCopy(value){const reason=value?.reasonCode;if(value?.status==="stale")return{title:"Goal changed since this review",body:"Refresh or reopen Goal Edit before saving so the current goal can be reviewed again."};if(reason==="REVIEW_TOKEN_EXPIRED")return{title:"Final Review expired",body:"Prepare Final Review again before saving."};if(["REVIEW_TOKEN_INVALID","REVIEW_TOKEN_VERSION_UNSUPPORTED","REVIEW_TOKEN_BINDING_MISMATCH","REVIEW_TOKEN_CONSUMED"].includes(reason))return{title:"Final Review needs to be prepared again",body:"This review can no longer be used to save changes."};if(value?.status==="failed")return{title:"Goal update could not be saved",body:value?.error?.message??value?.message??"The write did not complete. Your draft was preserved."};if(value?.status==="rejected")return{title:"Goal update needs attention",body:value?.message??value?.errors?.[0]?.message??"The reviewed changes could not be accepted."};return{title:"Goal update needs attention",body:value?.message??value?.recommendedAction??"Review the details and prepare Final Review again."}}
export function goalEditSaveKind(review){return review?.token?.version==="goal_phase_review_v1"?"phase":review?.token?.version==="goal_plan_review_v1"?"goal":"invalid"}
function PhaseButton({children,onClick}){return <button className="mt-2 min-h-12 w-full rounded-xl border border-[var(--divider)] px-3 text-sm font-extrabold" onClick={onClick}>{children}</button>}
function Fields({fields,values,onChange}){return <div className="space-y-4">{fields.map(([k,l])=><label className="block text-sm font-extrabold" key={k}>{l}<input className={input} onChange={e=>onChange(k,e.target.value)} value={values[k]??""}/></label>)}</div>}
function TargetTimeline({plan,onPatch}){return <OverallGoalEditor plan={plan} onPatch={onPatch}/>}
function OverallGoalEditor({plan,onPatch}){
 const [outcome,setOutcome]=useState(plan.target?.type!=="unspecified"?plan.target?.description??"":""),[startDate,setStartDate]=useState(plan.timeline?.startDate??""),[targetDate,setTargetDate]=useState(plan.timeline?.targetDate??plan.target?.targetDate??""),[guidance,setGuidance]=useState("");
 function changeOutcome(value){setOutcome(value);const result=interpretGoalOutcome(value);setGuidance(result.clarification??"");onPatch({primaryOutcome:value,target:result.status==="interpreted"?{...result.target,targetDate:targetDate||null}:{type:"unspecified",metric:null,direction:"unspecified",amount:null,unit:null,targetDate:targetDate||null,description:value||null}})}
 function changeStart(value){setStartDate(value);onPatch({timeline:{...plan.timeline,mode:targetDate?"target_date":"unspecified",startDate:value||null,targetDate:targetDate||null,eventDate:null,duration:null}})}
 function changeDate(value){setTargetDate(value);onPatch({target:{...plan.target,targetDate:value||null},timeline:{...plan.timeline,mode:value?"target_date":"unspecified",startDate:startDate||null,targetDate:value||null,eventDate:null,duration:null}})}
 return <div><h2 className="text-xl font-black">Overall goal</h2><p className="mt-2 text-sm leading-6 text-[var(--text-secondary)]">Where would you like this journey to end?</p><div className="mt-5 space-y-4"><label className="block text-sm font-extrabold">Goal outcome<textarea className={`${input} min-h-24`} value={outcome} onChange={e=>changeOutcome(e.target.value)}/></label>{guidance&&<p aria-live="polite" className="text-xs font-bold text-[var(--primary)]">{guidance}</p>}<label className="block text-sm font-extrabold">Journey begins<input className={input} type="date" value={startDate} onChange={e=>changeStart(e.target.value)}/></label><label className="block text-sm font-extrabold">Target date<input className={input} type="date" value={targetDate} onChange={e=>changeDate(e.target.value)}/></label></div><p className="mt-5 rounded-xl bg-[var(--surface-muted)] p-3 text-xs leading-5 text-[var(--text-secondary)]">This is the destination for the entire goal. Individual phase timing may change as evidence comes in, but this remains the target unless you choose to change it.</p></div>
}
function Items({draft,setDraft,collection,label:kind}){return <div>{draft.workingPlan[collection].map(x=><div key={x.key}><input className={input} value={x.label??""} onChange={e=>setDraft(editGoalEditItem(draft,collection,x.key,{label:e.target.value}))}/><button className="my-2 text-xs text-red-600" onClick={()=>setDraft(removeGoalEditItem(draft,collection,x.key))}>Remove</button></div>)}<PhaseButton onClick={()=>setDraft(addGoalEditItem(draft,collection,{label:`New ${kind}`}))}>Add {kind}</PhaseButton></div>}
function lines(v){return v.split("\n").map(x=>x.trim()).filter(Boolean).map((label,index)=>({key:`item_${index+1}`,label}))} function label(v){return typeof v==="string"?v:v?.label??v?.name??"Criterion"} function human(v){return String(v).replaceAll("_"," ")} function formatDate(value){if(!value)return "Not set";return new Intl.DateTimeFormat("en-US",{month:"long",day:"numeric",year:"numeric",timeZone:"UTC"}).format(new Date(`${value}T12:00:00Z`))} function overallDestination(plan){const t=plan.target??{};if(t.description&&t.type!=="unspecified")return `${t.description.replace(/[.]$/u,"")} ${t.targetDate?`by ${formatDate(t.targetDate)}`:""}.`.replace("  "," ");return t.description??null} function phaseDateSummary(phase){const end=phase.targetDate??estimatedPhaseTargetDate(phase);if(phase.startDate&&end)return `${formatDate(phase.startDate)} to ${formatDate(end)}`;if(end)return `Planned through ${formatDate(end)}`;return "We’ll decide together when it’s time to move on"} function title(s){return ({choose_sections:"Choose what to edit",goal_and_purpose:"Goal and purpose",overall_goal:"Overall goal",success_criteria:"Success criteria",guardrails:"Guardrails",coaching_preferences:"Coaching preferences",phases:"Phases",review:"Review Changes"})[s]??"Edit Goal"}
