  if (!draft.phaseEditing.workingAuthoredPhases.some((phase) => phase.id === phaseId)) throw new GoalEditPhaseDraftError("PHASE_NOT_FOUND", "Choose an authored phase.");
  const selectedIndex = draft.phaseEditing.workingAuthoredPhases.findIndex((phase) => phase.id === phaseId);
  const phases = draft.phaseEditing.workingAuthoredPhases.map((phase, index) => ({ ...structuredClone(phase), status: index < selectedIndex ? ([GoalPhaseStatus.COMPLETED, GoalPhaseStatus.SKIPPED].includes(phase.status) ? phase.status : GoalPhaseStatus.COMPLETED) : index === selectedIndex ? GoalPhaseStatus.ACTIVE : GoalPhaseStatus.UPCOMING }));
